// Sample photos and avatars for demo mode. Photos are free-to-use Pexels images loaded from
// the Pexels CDN; avatars are generated by DiceBear from a name. Real accounts use the photos
// and avatars people upload, never these.

const pexels = (id: number) =>
  `https://images.pexels.com/photos/${id}/pexels-photo-${id}.jpeg?auto=compress&cs=tinysrgb&w=640`;

export const DEMO_PHOTOS = {
  club: [7715518, 426976, 20557241, 40575996, 40575995, 14925306, 3379257, 15016142].map(pexels),
  live: [7715624, 13538521, 20407013, 38485786, 12289207].map(pexels),
  bar: [33231324, 16859953, 17192065, 1724521, 12923125, 12436820, 15700339, 8257973].map(pexels),
  dj: [2111016, 5191558, 2381596].map(pexels),
} as const;

/** Memoji-style avatar for a sample person. */
export function demoAvatar(seed: string): string {
  return `https://api.dicebear.com/9.x/avataaars/png?seed=${encodeURIComponent(seed)}&size=128&backgroundColor=b6e3f4,c0aede,d1d4f9,ffd5dc,ffdfbf`;
}
